  const items=featureCatalog.filter(x=>x.category==='Campus services')
  return <><PageHero kicker="CAMPUS SERVICES" title="The services around" accent="the learning experience." description="Explore the campus-service areas named on the current public EduSphere 360 site. The page preserves the availability distinction shown in the current release description."/><section className="ep-section"><div className="ep-feature-grid">{items.map(item=><FeatureCard key={item.slug} feature={item}/>)}</div></section></>
