export function PublicPageScreen({page,navigate}:{page:string;navigate:Navigate}) {
  useEffect(()=>{window.scrollTo({top:0,behavior:'auto'})},[page])
  const parts=page.split('/').filter(Boolean)
  const pageKey=parts[0]||'features'
  const slug=parts[1]
  const selectedFeature=slug?featureCatalog.find(item=>item.slug===slug):undefined
  let content:ReactNode
  if(pageKey==='features'&&selectedFeature) content=<FeatureDetail feature={selectedFeature}/>
  else if(pageKey==='features') content=<FeatureCatalogue/>
  else if(pageKey==='solutions') content=<SolutionsPage/>
  else if(pageKey==='analytics') content=<AnalyticsPage/>
  else if(pageKey==='about') content=<AboutPage/>
  else if(pageKey==='pricing') content=<PricingPage navigate={navigate}/>
  else if(pageKey==='mobile') content=<MobilePage/>
  else if(pageKey==='integrations') content=<IntegrationsPage/>
  else if(pageKey==='reviews') content=<ReviewsPage/>
  else if(pageKey==='resources') content=<ResourcesPage/>
  else if(pageKey==='support'||pageKey==='contact'||pageKey==='faq') content=<SupportPage navigate={navigate}/>
  else if(pageKey==='updates') content=<UpdatesPage/>
  else if(pageKey==='product-tour') content=<ProductTourPage/>
  else if(pageKey==='campus-services') content=<CampusServicesPage/>
  else content=<FeatureCatalogue/>
  return <div className="edm-home edm-public-page"><PublicHeader navigate={navigate}/><main className="ep-public-main" id="top">{content}</main><PublicFooter navigate={navigate}/></div>
}
